local module = {}
module.__index = module
module.className = "Connection"
module.All = {}
module._sourceConnectionsEnabled = true

function module._destroy(name)
	local connections = module.All[name]
	if connections then
		for i, v in pairs(connections) do
			if v.Destroy then
				v:Destroy()
			end
		end
		table.clear(module.All[name])
        module.All[name] = nil
	end
end

function module._add(name, connection)
	if name == nil then
		warn(`[Neza] Connection:Named: ${name} is nil`)
		warn(debug.traceback())
		return
	end
	if not module.All[name] then
		module.All[name] = {}
	end
	
	local source = connection.Source
	if name ~= source and module.All[source] then
		local idx = table.find(module.All[source], connection)
		if idx then
			table.remove(module.All[source], idx)
		end
	end
	
	if not table.find(module.All[name], connection) then
		table.insert(module.All[name], connection)
		connection.Name = name
	end
end

function module.SetSourceConnectionsEnabled(enabled)
    module._sourceConnectionsEnabled = enabled
end

function module.GetEnable(connection)
    if connection.Source then
        return module._sourceConnectionsEnabled
    end
    return true
end

function module.new(eventOrEvents, func, inst, ...)
    local self = {}
    self.Event = eventOrEvents
    if typeof(eventOrEvents) ~= "table" then
        self.Event = {eventOrEvents}
    end
    self.Target = func
    self._enabled = true
    self._connections = nil
    self.ran = false
    setmetatable(self, module)
    self._destroyed = false
    self._catch = nil
    self._expections = nil
    if inst then
        self._instArgs = {...}
    end
    -- self:_connect()
    -- 下一帧连接
    task.spawn(self._connect, self)
    return self
end

function module.once(eventOrEvents, func)
    local self = {}
    self.Event = eventOrEvents
    self.Target = func
    self._enabled = true
    self._connections = nil
    setmetatable(self, module)
    self._destroyed = false
    self._catch = nil
    self._expections = nil
    self._once = true
    -- self:_connect()
    -- 下一帧连接
    task.spawn(self._connect, self, true)
    return self
end

function module:_connect(once)
    self._connections = {}
    for i, e in pairs(self.Event) do
        local exe = function(...)
            if self._enabled and self:_getExpected(...) and module.GetEnable(self) then
                self.Target(...)
                if once then
                    self:Disconnect()
                end
            end
        end
        if typeof(e) == "RBXScriptSignal" then
            local c = e:Connect(exe)
            table.insert(self._connections, c)
        else
            warn(`[Neza] {tostring(e)} is not a RBXScriptSignal`)
		    warn(debug.traceback())
        end

        if self._instArgs then
            task.defer(exe, table.unpack(self._instArgs))
        end
    end
end

function module:_getExpected(arg)
    if not self._expections then
        return true
    end
    for i, v in pairs(self._expections) do
        if arg == v then
            return true
        end
    end
end

function module:Named(name)
    
	module._add(name, self)
	
    return self
end

function module:Expect(...)
    self._expections = {...}
    return self
end

function module:Catch(func)
    self._catch = func
    return self
end

function module:Finally(func)
    self._finally = func
    return self
end

function module:Then(func)
    self._then = func
    return self
end


function module:Disconnect()
    for i, v in pairs(self._connections) do
        v:Disconnect()
	end
	table.clear(self._connections)
end

function module:SetEnabled(enabled)
    if enabled == nil then
        enabled = true
    end
    self._enabled = enabled
end

function module:Disable()
    self:SetEnabled(false)
end
function module:Enable()
    self:SetEnabled(true)
end


function module:Destroy()
    self:Disable()
    self:Disconnect()
	self._destroyed = true
	for i, v in pairs(self) do
		if typeof(v) == "table" then
			table.clear(v)
		end
	end
    table.clear(self)
    setmetatable(self, nil)
end

return module